// @ts-check
const { test, expect } = require('@playwright/test');
const {
	createSeededRepository,
	deleteRepository,
	repositoryPageUrl,
	serverBaseUrl,
	setQueryEditor,
	uniqueRepositoryId,
	waitForRoute,
	workbenchBaseUrl
} = require('./workbench-test-helpers.js');

// Round-3 exploratory testing of GH-6071: focus, full screen, narrow layout and form checks, in real browsers.
const REPOSITORY_ID = uniqueRepositoryId('workbench-round3-forms');
const PRODUCT = '<http://www4.wiwiss.fu-berlin.de/bizer/bsbm/v01/instances/dataFromProducer1/Product1>';
const LONG_IRI = 'http://example.org/very/long/path/'
	+ Array.from({ length: 12 }, (_, index) => `segment-number-${index}-with-extra-words`).join('/')
	+ '#fragmentIdentifierThatIsAlsoQuiteLong';
const LONG_LABEL = 'AVeryLongLabelWithoutAnySpacesInIt'.repeat(5);
const LONG_TYPE = 'http://example.org/types/' + 'AnExtremelyLongTypeNameWithoutBreaks'.repeat(3);
const LONG_COMMENT = 'Acommentwithoutanyspaces'.repeat(12) + ' and then a few ordinary words.';

test.beforeAll(async ({ request }) => {
	const repositoryUrl = await createSeededRepository(request, serverBaseUrl(), REPOSITORY_ID);
	const loaded = await request.post(`${repositoryUrl}/statements`, {
		headers: { 'Content-Type': 'text/turtle' },
		data: `<${LONG_IRI}> a <${LONG_TYPE}> ;
			<http://www.w3.org/2000/01/rdf-schema#label> "${LONG_LABEL}" ;
			<http://www.w3.org/2000/01/rdf-schema#comment> "${LONG_COMMENT}" .`
	});
	expect(loaded.status()).toBe(204);
});

test.afterAll(async ({ request }) => {
	await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

/** The computed outline of the element a locator finds. */
function outlineOf(locator) {
	return locator.evaluate((element) => {
		const style = getComputedStyle(element);
		return { style: style.outlineStyle, width: parseFloat(style.outlineWidth) || 0 };
	});
}

/** Whether the Workbench keyboard focus indicator is drawn: a visible outline of at least 2px. */
function drawsRing(outline) {
	return outline.style !== 'none' && outline.width >= 2;
}

/** Whether any outline is drawn, including a browser's own focus ring (Chrome draws 'auto 1px'). */
function showsOutline(outline) {
	return outline.style !== 'none' && outline.width > 0;
}

/** Safari moves focus to buttons with Option+Tab only. */
function tabKey(browserName) {
	return browserName === 'webkit' ? 'Alt+Tab' : 'Tab';
}

/** Focuses a control the way a keyboard user does, so that it matches :focus-visible. */
async function keyboardFocus(page, control, browserName) {
	await control.focus();
	await page.keyboard.press(tabKey(browserName));
	await page.keyboard.press(`Shift+${tabKey(browserName)}`);
	if (!(await control.evaluate((element) => element === document.activeElement))) {
		await control.focus();
	}
}

async function openRemoveWithMatches(page) {
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'remove'), { waitUntil: 'domcontentloaded' });
	await waitForRoute(page, 'remove');
	const form = page.locator('#remove-form');
	await form.locator('#subj').fill(PRODUCT);
	await expect(form.locator('#remove-count')).toHaveText(/^\d+ statements match$/);
	const action = form.locator('button[type="submit"]');
	await expect(action).toBeEnabled();
	return action;
}

test.describe('C1 focus after dialogs and clicks', () => {
	test('a confirm dialog closed with the mouse returns focus to its opener without a ring around the page',
		async ({ page, browserName }) => {
			await page.setViewportSize({ width: 1280, height: 800 });
			const action = await openRemoveWithMatches(page);
			await action.click();
			const dialog = page.locator('dialog[open]');
			await expect(dialog).toHaveCount(1);
			await dialog.getByRole('button', { name: 'Cancel' }).click();
			await expect(dialog).toHaveCount(0);

			await expect(action).toBeFocused();
			expect(showsOutline(await outlineOf(page.locator('#workbench-outlet'))), 'ring around the page').toBe(false);
			// Safari counts every focus a script moves as keyboard focus (:focus-visible), the dialog's Cancel button
			// when it opens as much as the opener when it closes; the other browsers keep the mouse's no-ring state.
			if (browserName !== 'webkit') {
				expect(showsOutline(await outlineOf(action)), 'ring on the opener after a mouse click').toBe(false);
			}
		});

	test('a confirm dialog closed with Escape returns keyboard focus, with its ring, to its opener',
		async ({ page, browserName }) => {
			await page.setViewportSize({ width: 1280, height: 800 });
			const action = await openRemoveWithMatches(page);
			await keyboardFocus(page, action, browserName);
			await page.keyboard.press('Enter');
			const dialog = page.locator('dialog[open]');
			await expect(dialog).toHaveCount(1);
			await expect(dialog.getByRole('button', { name: 'Cancel' })).toBeFocused();
			await page.keyboard.press('Escape');
			await expect(dialog).toHaveCount(0);

			await expect(action).toBeFocused();
			expect(drawsRing(await outlineOf(action)), 'keyboard focus indicator on the opener').toBe(true);
			expect(showsOutline(await outlineOf(page.locator('#workbench-outlet'))), 'ring around the page').toBe(false);
		});

	test('a confirm dialog opened from a namespace row returns focus to that row action', async ({ page }) => {
		await page.setViewportSize({ width: 1280, height: 800 });
		await page.goto(repositoryPageUrl(REPOSITORY_ID, 'namespaces'), { waitUntil: 'domcontentloaded' });
		await waitForRoute(page, 'namespaces');
		const row = page.locator('#workbench-outlet tbody tr').first();
		const prefix = (await row.locator('td').first().innerText()).trim();
		const remove = row.getByRole('button', { name: `Delete ${prefix}`, exact: true });
		await row.hover();
		await remove.click();
		const dialog = page.locator('dialog[open]');
		await expect(dialog).toHaveCount(1);
		await dialog.getByRole('button', { name: 'Cancel' }).click();
		await expect(dialog).toHaveCount(0);

		await expect(remove).toBeFocused();
		expect(showsOutline(await outlineOf(page.locator('#workbench-outlet'))), 'ring around the page').toBe(false);
	});

	test('a confirm dialog that opens after the Create id check returns focus to Create', async ({ page }) => {
		const id = await openCreateMemory(page);
		await id.fill('Round3_Unusual');
		await page.locator('#create').click();
		const dialog = page.getByRole('dialog', { name: 'Use this repository id?' });
		await expect(dialog).toBeVisible();
		await dialog.getByRole('button', { name: 'Cancel' }).click();
		await expect(dialog).toHaveCount(0);

		await expect(page.locator('#create')).toBeFocused();
		expect(showsOutline(await outlineOf(page.locator('#workbench-outlet'))), 'ring around the page').toBe(false);
		await expect(page).toHaveURL(/\/create\?type=memory$/);
	});

	for (const view of ['summary', 'query']) {
		test(`a click on blank ${view} page space followed by a key press draws no ring around the page`,
			async ({ page }) => {
				await page.setViewportSize({ width: 1280, height: 800 });
				await page.goto(repositoryPageUrl(REPOSITORY_ID, view), { waitUntil: 'domcontentloaded' });
				await waitForRoute(page, view);
				const point = await page.locator('#workbench-page-surface').evaluate((surface) => {
					const bounds = surface.getBoundingClientRect();
					return { x: bounds.right - 30, y: bounds.top + 12 };
				});
				await page.mouse.click(point.x, point.y);
				await page.keyboard.press('Escape');

				const outlet = page.locator('#workbench-outlet');
				expect(showsOutline(await outlineOf(outlet)), 'ring around the page').toBe(false);
			});
	}
});

test.describe('C3 full-screen editor', () => {
	for (const view of ['query', 'update']) {
		test(`the full-screen ${view} editor fills the screen, keeps focus and leaves full screen with Escape`,
			async ({ page }) => {
				await page.setViewportSize({ width: 1280, height: 800 });
				await page.goto(repositoryPageUrl(REPOSITORY_ID, view), { waitUntil: 'domcontentloaded' });
				await waitForRoute(page, view);
				const lines = Array.from({ length: 60 }, (_, index) => `# line ${index + 1}`).join('\n');
				await setQueryEditor(page, lines + '\nSELECT * WHERE { ?s ?p ?o } LIMIT 1');
				const editor = page.locator('#workbench-outlet .CodeMirror').first();
				await editor.locator('.yasqe_fullscreenBtn').click();
				await expect(editor).toHaveClass(/CodeMirror-fullscreen/);

				const layout = await editor.evaluate((element) => {
					const scroller = element.querySelector('.CodeMirror-scroll').getBoundingClientRect();
					const wrapper = element.getBoundingClientRect();
					return { scroller: scroller.height, wrapper: wrapper.height, viewport: window.innerHeight };
				});
				expect(layout.wrapper, 'the editor covers the viewport').toBeGreaterThanOrEqual(layout.viewport - 2);
				expect(layout.scroller, 'the text area covers the full-screen editor').toBeGreaterThanOrEqual(
					layout.viewport * 0.95);
				expect(await editor.evaluate((element) => element.contains(document.activeElement)),
					'focus moves into the full-screen editor').toBe(true);

				await page.keyboard.press('Escape');
				await expect(editor).not.toHaveClass(/CodeMirror-fullscreen/);
				expect(await editor.evaluate((element) => element.contains(document.activeElement)),
					'focus stays in the editor').toBe(true);
				expect(await page.evaluate(() => document.documentElement.style.overflow),
					'the page scrolls again').toBe('');
			});
	}

	test('Escape leaves full screen even when focus left the editor', async ({ page }) => {
		await page.setViewportSize({ width: 1280, height: 800 });
		await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'), { waitUntil: 'domcontentloaded' });
		await waitForRoute(page, 'query');
		const editor = page.locator('#workbench-outlet .CodeMirror').first();
		await editor.locator('.yasqe_fullscreenBtn').click();
		await expect(editor).toHaveClass(/CodeMirror-fullscreen/);
		await page.evaluate(() => {
			const active = /** @type {HTMLElement} */ (document.activeElement);
			if (active && active.blur) { active.blur(); }
		});
		await page.keyboard.press('Escape');
		await expect(editor).not.toHaveClass(/CodeMirror-fullscreen/);
	});
});

test.describe('C5 explored resource on a phone', () => {
	for (const colorScheme of /** @type {const} */ (['light', 'dark'])) {
		test(`a long IRI, label, type and comment stay inside a 390px wide screen (${colorScheme})`, async ({ page }) => {
			await page.emulateMedia({ colorScheme });
			await page.setViewportSize({ width: 390, height: 844 });
			await page.goto(repositoryPageUrl(REPOSITORY_ID, 'explore') + '?resource=' + encodeURIComponent(`<${LONG_IRI}>`),
				{ waitUntil: 'domcontentloaded' });
			await waitForRoute(page, 'explore');
			const card = page.locator('#explore-resource-card');
			await expect(card.locator('h2')).toHaveText(LONG_LABEL);

			const fit = await card.evaluate((element) => {
				const bounds = element.getBoundingClientRect();
				const outside = Array.from(element.querySelectorAll('*'))
					.filter((child) => {
						const box = child.getBoundingClientRect();
						return box.width > 0 && (box.right > bounds.right + 1 || box.left < bounds.left - 1);
					})
					.map((child) => child.tagName + '.' + String(child.className).split(' ')[0]);
				return {
					documentWidth: document.documentElement.scrollWidth,
					viewport: window.innerWidth,
					cardRight: Math.round(bounds.right),
					cardOverflow: element.scrollWidth - element.clientWidth,
					outside
				};
			});
			expect(fit.outside, 'card content outside the card').toEqual([]);
			expect(fit.cardOverflow).toBeLessThanOrEqual(1);
			expect(fit.cardRight).toBeLessThanOrEqual(fit.viewport);
			expect(fit.documentWidth, 'no horizontal page scroll').toBeLessThanOrEqual(fit.viewport);
		});
	}
});

/** Opens the Create form of a memory store and returns its id field. */
async function openCreateMemory(page) {
	await page.setViewportSize({ width: 1280, height: 900 });
	await page.goto(`${workbenchBaseUrl()}/repositories/NONE/create?type=memory`, { waitUntil: 'domcontentloaded' });
	await waitForRoute(page, 'create');
	const id = page.locator('form[action="create"] [data-field-role="repository-id"]');
	await expect(id).toBeVisible();
	return id;
}

test.describe('C14 and C26 repository ids on Create', () => {
	test('an id with characters a repository id cannot have is explained, not offered', async ({ page }) => {
		const requests = [];
		page.on('request', (request) => requests.push(request.url()));
		const id = await openCreateMemory(page);
		const create = page.locator('#create');
		const before = requests.length;
		await id.fill('bad id/with slash');

		// The server's rule and message (CreateServlet answers such an id with 400 and the same text).
		const error = page.locator('#repository-id-error');
		await expect(error).toBeVisible();
		await expect(error).toHaveText("Repository ID 'bad id/with slash' is not valid: use only the letters a-z and "
			+ "A-Z, digits, '-', '_', '.' and '@', and not only dots.");
		await expect(id).toHaveAttribute('aria-invalid', 'true');
		await expect(id).toHaveAttribute('aria-describedby', 'repository-id-error');
		await expect(create).toBeDisabled();
		await expect(page.locator('dialog[open]')).toHaveCount(0);
		expect(requests.slice(before).filter((url) => /\/(info|repositories)(\?|$)/.test(url)),
			'no existence check for an invalid id').toEqual([]);
		await expect(page).toHaveURL(/\/create\?type=memory$/);

		await id.fill('');
		await expect(error).toHaveText('Enter a repository ID.');
		await expect(create).toBeDisabled();

		await id.fill('round3-valid');
		await expect(error).toBeHidden();
		await expect(id).not.toHaveAttribute('aria-invalid', 'true');
		await expect(create).toBeEnabled();
	});

	test('Create checks a new id without a failing request and creates the repository', async ({ page, request }) => {
		const created = uniqueRepositoryId('round3-create');
		const failures = [];
		page.on('console', (message) => {
			if (message.type() === 'error') { failures.push('console: ' + message.text()); }
		});
		page.on('response', (response) => {
			if (response.status() >= 400) { failures.push(`HTTP ${response.status()} ${response.url()}`); }
		});
		try {
			const id = await openCreateMemory(page);
			await id.fill(created);
			await page.locator('#create').click();
			await waitForRoute(page, 'summary', { url: (url) => url.pathname.endsWith(`/${created}/summary`) });
			expect(failures).toEqual([]);
		} finally {
			await deleteRepository(request, serverBaseUrl(), created);
		}
	});

	test('the federation form explains an id a repository id cannot have and keeps Create disabled', async ({ page, request }) => {
		const member = uniqueRepositoryId('round3-member');
		await createSeededRepository(request, serverBaseUrl(), member);
		try {
			await page.goto(`${workbenchBaseUrl()}/repositories/NONE/create?type=federate`);
			await waitForRoute(page, 'create');
			await page.locator(`input.memberID[value="${REPOSITORY_ID}"]`).check();
			await page.locator(`input.memberID[value="${member}"]`).check();
			const id = page.locator('#id');
			const create = page.locator('#create');
			const error = page.locator('#repository-id-error');

			await id.fill('bad id');
			await expect(error).toHaveText("Repository ID 'bad id' is not valid: use only the letters a-z and "
				+ "A-Z, digits, '-', '_', '.' and '@', and not only dots.");
			await expect(create).toBeDisabled();

			await id.fill('round3-federation');
			await expect(error).toBeHidden();
			await expect(create).toBeEnabled();
		} finally {
			await deleteRepository(request, serverBaseUrl(), member);
		}
	});

	test('Create still asks before replacing an existing repository', async ({ page }) => {
		const failures = [];
		page.on('response', (response) => {
			if (response.status() >= 400) { failures.push(`HTTP ${response.status()} ${response.url()}`); }
		});
		const id = await openCreateMemory(page);
		await id.fill(REPOSITORY_ID);
		await page.locator('#create').click();
		const dialog = page.getByRole('dialog', { name: 'Replace repository configuration?' });
		await expect(dialog).toBeVisible();
		await dialog.getByRole('button', { name: 'Cancel' }).click();
		await expect(dialog).toHaveCount(0);
		await expect(page).toHaveURL(/\/create\?type=memory$/);
		expect(failures).toEqual([]);
	});
});

test.describe('C15 Connection credentials', () => {
	test('a password with characters outside Latin-1 is sent as UTF-8 base64', async ({ page }) => {
		const errors = [];
		page.on('pageerror', (error) => errors.push(error.message));
		await page.setViewportSize({ width: 1280, height: 900 });
		await page.goto(`${workbenchBaseUrl()}/repositories/NONE/server`, { waitUntil: 'domcontentloaded' });
		await waitForRoute(page, 'server');
		await page.locator('#workbench-server').fill(serverBaseUrl());
		await page.locator('#server-auth-toggle').click();
		await page.locator('#server-user').fill('wbtestuser');
		await page.locator('#server-password').fill('pass✓ é');
		const posted = page.waitForRequest((request) => request.method() === 'POST'
			&& new URL(request.url()).pathname.endsWith('/server'), { timeout: 10000 });
		await page.locator('#server-password').press('Enter');
		const sent = await posted.catch(() => null);
		expect(errors, 'script errors while submitting').toEqual([]);
		expect(sent, 'the form is sent').not.toBeNull();
		const body = sent.postData() || '';
		const contentType = (await sent.allHeaders())['content-type'] || '';
		const value = contentType.includes('multipart/form-data')
			? (body.match(/name="server-user-password"\r\n\r\n([^\r]*)\r\n/) || [])[1]
			: new URLSearchParams(body).get('server-user-password');
		expect(value).toBe(Buffer.from('wbtestuser:pass✓ é', 'utf8').toString('base64'));
	});
});

test.describe('C16 action focus rings', () => {
	/** Presses the pointer on a control and lets go elsewhere, so the press focuses it without activating it. */
	async function pressWithoutClick(page, control) {
		const box = await control.boundingBox();
		await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
		await page.mouse.down();
		const outline = await outlineOf(control.locator('xpath=ancestor-or-self::*[contains(concat(" ", @class, " "), " workbench-action ")][1]'));
		const self = await outlineOf(control);
		await page.mouse.move(2, 2);
		await page.mouse.up();
		return { outline, self };
	}

	test('a pointer press on an action button draws no focus ring; keyboard focus does', async ({ page, browserName }) => {
		await page.setViewportSize({ width: 1280, height: 900 });
		await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'), { waitUntil: 'domcontentloaded' });
		await waitForRoute(page, 'query');
		const execute = page.locator('#exec');
		const pressed = await pressWithoutClick(page, execute);
		expect(showsOutline(pressed.outline), `Execute after a pointer press: ${JSON.stringify(pressed)}`).toBe(false);
		await keyboardFocus(page, execute, browserName);
		expect(drawsRing(await outlineOf(execute)), 'Execute with keyboard focus').toBe(true);

		await page.goto(`${workbenchBaseUrl()}/repositories/NONE/create`, { waitUntil: 'domcontentloaded' });
		await waitForRoute(page, 'create');
		const next = page.locator('#create-type-form input[type="submit"]');
		const wrapper = page.locator('#create-type-form .workbench-action');
		const wrapped = await pressWithoutClick(page, next);
		expect(showsOutline(wrapped.outline), `Next after a pointer press: ${JSON.stringify(wrapped)}`).toBe(false);
		expect(showsOutline(wrapped.self)).toBe(false);
		await keyboardFocus(page, next, browserName);
		expect(drawsRing(await outlineOf(wrapper)), 'Next with keyboard focus').toBe(true);
	});
});
